.la-ul {
  list-style-type: none;
  margin-left: 2.5em;
  padding-left: 0;
}
.la-ul > li {
  position: relative;
}
.la-li {
  left: -2em;
  position: absolute;
  text-align: center;
  width: 2em;
  line-height: inherit;
}
.la-border {
  border: solid 0.08em #eee;
  border-radius: 0.1em;
  padding: 0.2em 0.25em 0.15em;
}
.la-pull-left {
  float: left;
}
.la-pull-right {
  float: right;
}
.la.la-pull-left,
.lab.la-pull-left,
.lal.la-pull-left,
.lar.la-pull-left,
.las.la-pull-left {
  margin-right: 0.3em;
}
.la.la-pull-right,
.lab.la-pull-right,
.lal.la-pull-right,
.lar.la-pull-right,
.las.la-pull-right {
  margin-left: 0.3em;
}
.la-spin {
  -webkit-animation: la-spin 2s infinite linear;
  animation: la-spin 2s infinite linear;
}
.la-pulse {
  -webkit-animation: la-spin 1s infinite steps(8);
  animation: la-spin 1s infinite steps(8);
}
@-webkit-keyframes la-spin {
  0% {
    -webkit-transform: rotate(0);
    transform: rotate(0);
  }
  100% {
    -webkit-transform: rotate(360deg);
    transform: rotate(360deg);
  }
}
@keyframes la-spin {
  0% {
    -webkit-transform: rotate(0);
    transform: rotate(0);
  }
  100% {
    -webkit-transform: rotate(360deg);
    transform: rotate(360deg);
  }
}
.la-rotate-90 {
  -webkit-transform: rotate(90deg);
  transform: rotate(90deg);
}
.la-rotate-180 {
  -webkit-transform: rotate(180deg);
  transform: rotate(180deg);
}
.la-rotate-270 {
  -webkit-transform: rotate(270deg);
  transform: rotate(270deg);
}
.la-flip-horizontal {
  -webkit-transform: scale(-1, 1);
  transform: scale(-1, 1);
}
.la-flip-vertical {
  -webkit-transform: scale(1, -1);
  transform: scale(1, -1);
}
.la-flip-both,
.la-flip-horizontal.la-flip-vertical {
  -webkit-transform: scale(-1, -1);
  transform: scale(-1, -1);
}
:root .la-flip-both,
:root .la-flip-horizontal,
:root .la-flip-vertical,
:root .la-rotate-180,
:root .la-rotate-270,
:root .la-rotate-90 {
  -webkit-filter: none;
  filter: none;
}
.la-stack {
  display: inline-block;
  height: 2em;
  line-height: 2em;
  position: relative;
  vertical-align: middle;
  width: 2.5em;
}
.la-stack-1x,
.la-stack-2x {
  left: 0;
  position: absolute;
  text-align: center;
  width: 100%;
}
.la-stack-1x {
  line-height: inherit;
}
.la-stack-2x {
  font-size: 2em;
}
.la-inverse {
  color: #fff;
